// Technical validation only. AI owns business/lead qualification.
const raw = $json.body ?? $json;
const str = v => (v === undefined || v === null) ? '' : String(v).trim().replace(/\s+/g, ' ');
const errors = [];

const name = str(raw.name).slice(0, 120);
const email = str(raw.email).toLowerCase().slice(0, 254);
const company = str(raw.company).slice(0, 160);
const source = str(raw.source).slice(0, 80) || 'webform';
const message = str(raw.message).slice(0, 2000);
const honeypot = str(raw.website);
const consent = raw.consent === true || raw.consent === 'true';

let phone = str(raw.phone).replace(/[^\d+]/g, '');
if (phone.startsWith('00')) phone = '+' + phone.slice(2);
const phoneDigits = phone.replace(/\D/g, '');
if (phone && (phoneDigits.length < 8 || phoneDigits.length > 15)) {
  errors.push('invalid_phone');
  phone = '';
}

if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('invalid_email');
if (!name) errors.push('missing_name');
if (!message) errors.push('missing_message');
if (honeypot) errors.push('spam_honeypot');
if (!consent) errors.push('consent_required');

let h = 5381;
for (const c of email + '|' + phoneDigits + '|' + message) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0;

const valid = errors.length === 0;
return [{ json: {
  valid,
  status: valid ? 'new' : 'invalid',
  errors,
  received_at: new Date().toISOString(),
  idempotency_key: 'L' + h.toString(36),
  name, email, phone, phone_digits: phoneDigits,
  company, source, message, consent
}}];

// Duplicate = same email OR same normalized phone processed in the last 24h.
// For this portfolio demo the audit log is read as a small dataset. For high-volume production,
// move this lookup to PostgreSQL/CRM search rather than scanning the whole Sheet.
const lead = $('Validate & Clean').first().json;
const WINDOW_MS = 24 * 60 * 60 * 1000;
const now = Date.now();
const normalizeEmail = v => String(v ?? '').trim().toLowerCase();
const normalizePhone = v => String(v ?? '').replace(/\D/g, '');
const rows = $input.all().map(i => i.json).filter(r => r && (r.email || r.phone));

const recent = rows.find(r => {
  const received = Date.parse(r.received_at);
  const withinWindow = Number.isFinite(received) && now - received >= 0 && now - received < WINDOW_MS;
  if (!withinWindow) return false;

  const sameEmail = Boolean(lead.email) && normalizeEmail(r.email) === lead.email;
  const samePhone = Boolean(lead.phone_digits) && normalizePhone(r.phone) === lead.phone_digits;
  const processed = ['qualified', 'fallback'].includes(String(r.status || '').toLowerCase());
  return processed && (sameEmail || samePhone);
});

return [{ json: {
  ...lead,
  is_duplicate: Boolean(recent),
  status: recent ? 'duplicate' : 'new',
  duplicate_of: recent ? (recent.idempotency_key || '') : '',
  duplicate_match: recent
    ? (normalizeEmail(recent.email) === lead.email ? 'email' : 'phone')
    : ''
}}];

// Build an AI qualification request from the lead's unstructured business context.
// The AI is responsible for deciding whether the lead has enough information to qualify.
const MODEL = 'gpt-4o-mini';
const lead = $json;

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    qualification_status: {
      type: 'string',
      enum: ['qualified', 'invalid'],
      description: 'qualified only when the core business signals required by this portfolio are present and usable; otherwise invalid'
    },
    requirement: {
      type: 'string',
      description: 'The customer requirement or business problem, grounded in the message'
    },
    product_requested: {
      type: 'string',
      description: 'The product or service requested, grounded in the message'
    },
    budget_signal: {
      type: 'string',
      enum: ['none', 'low', 'mid', 'high'],
      description: 'none only when no usable budget information is stated'
    },
    urgency: {
      type: 'string',
      enum: ['low', 'medium', 'high'],
      description: 'Derived strictly from the intended usage/start timing stated by the lead'
    },
    fit: {
      type: 'integer',
      description: '0-10, how well the request matches the automation agency services'
    },
    intent: {
      type: 'integer',
      description: '0-10, explicit buying/implementation intent from the message'
    },
    pain_points: {
      type: 'array',
      items: { type: 'string' }
    },
    next_action: {
      type: 'string',
      description: 'One concrete sales action supported by the evidence'
    },
    summary: {
      type: 'string'
    },
    missing_information: {
      type: 'array',
      items: { type: 'string' },
      description: 'Required business information that is absent or unusable'
    },
    qualification_reason: {
      type: 'string',
      description: 'Why the lead is qualified or invalid, based only on evidence in the request'
    }
  },
  required: [
    'qualification_status',
    'requirement',
    'product_requested',
    'budget_signal',
    'urgency',
    'fit',
    'intent',
    'pain_points',
    'next_action',
    'summary',
    'missing_information',
    'qualification_reason'
  ]
};

const system = [
  'You qualify inbound B2B leads for an automation agency (n8n, AI, CRM integrations).',
  'Treat the lead message as unstructured input. Do not assume the visitor selected or knows any qualification category.',
  'Extract facts only from the supplied business context. Never invent budget, timing, requirements, pain points, or buying signals.',
  'For this portfolio qualification gate, the core evidence is: (1) a clear product/service or business requirement, (2) explicit budget information or budget range, and (3) explicit intended timing/start/usage window.',
  'Set qualification_status=invalid when any core evidence is missing, contradictory, or too vague to use. Put the missing items into missing_information. Do not make an invalid lead look qualified by guessing.',
  'budget_signal: low < 1000 EUR, mid = 1000-5000 EUR, high > 5000 EUR; none = not stated or not usable.',
  'urgency: high = explicit deadline, immediate need or use/start this month; medium = this quarter / within about 90 days; low = later but still a stated plan. If no usable timing is stated, qualification_status must be invalid.',
  'fit and intent are 0-10. Fit measures service match; intent measures explicit willingness/readiness to implement or buy. Do not infer either from personal data.',
  'If the message is in French or English, answer in English.',
  'next_action must be concrete and evidence-based. qualification_reason must briefly explain the decision.',
  'For invalid leads, keep fit and intent at 0, use budget_signal=none or the extracted signal, and use urgency=low only as a placeholder if timing is missing.'
].join('\n');

const user = JSON.stringify({
  company: lead.company,
  source: lead.source,
  message: lead.message
});

return [{ json: {
  lead,
  body: {
    model: MODEL,
    temperature: 0,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user }
    ],
    response_format: {
      type: 'json_schema',
      json_schema: { name: 'lead_qualification', strict: true, schema }
    }
  }
}}];

// Parse AI JSON, validate it, apply the AI qualification gate, then compute a deterministic 0-100 score.
// AI interprets the request; n8n rules own the final score/classification.
const lead = $('Build AI Request').first().json.lead;
const res = $json;

const W_FIT = 3;       // max 30 — description/service fit
const W_INTENT = 2;    // max 20 — explicit buying/implementation intent
const BUDGET_POINTS = { none: 0, low: 5, mid: 15, high: 25 }; // max 25 — explicit budget
const URGENCY_POINTS = { low: 5, medium: 15, high: 25 };       // max 25 — stated timing
const HOT = 70;
const WARM = 40;

const clamp = n => {
  const value = Number(n);
  return Number.isFinite(value) ? Math.max(0, Math.min(10, Math.round(value))) : 0;
};

let ai = null;
let ai_status = 'ok';
let ai_error = '';

try {
  if (res.error) throw new Error(typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error)));
  const msg = res.choices?.[0]?.message;
  if (!msg) throw new Error('empty_ai_response');
  if (msg.refusal) throw new Error('ai_refusal: ' + msg.refusal);

  ai = typeof msg.content === 'string' ? JSON.parse(msg.content) : msg.content;
  if (!ai || typeof ai !== 'object') throw new Error('invalid_ai_object');
  if (!['qualified','invalid'].includes(ai.qualification_status)) throw new Error('bad_qualification_status');
  if (!(ai.budget_signal in BUDGET_POINTS)) throw new Error('bad_budget_signal');
  if (!(ai.urgency in URGENCY_POINTS)) throw new Error('bad_urgency');
  if (!Number.isInteger(ai.fit) || ai.fit < 0 || ai.fit > 10) throw new Error('bad_fit');
  if (!Number.isInteger(ai.intent) || ai.intent < 0 || ai.intent > 10) throw new Error('bad_intent');
  if (!Array.isArray(ai.pain_points) || !ai.pain_points.every(v => typeof v === 'string')) throw new Error('bad_pain_points');
  if (!Array.isArray(ai.missing_information) || !ai.missing_information.every(v => typeof v === 'string')) throw new Error('bad_missing_information');
  if (typeof ai.requirement !== 'string') throw new Error('bad_requirement');
  if (typeof ai.product_requested !== 'string') throw new Error('bad_product_requested');
  if (typeof ai.next_action !== 'string' || !ai.next_action) throw new Error('missing_next_action');
  if (typeof ai.summary !== 'string' || !ai.summary) throw new Error('missing_summary');
  if (typeof ai.qualification_reason !== 'string' || !ai.qualification_reason) throw new Error('missing_qualification_reason');

  ai.pain_points = ai.pain_points.slice(0, 5).map(v => v.slice(0, 160));
  ai.missing_information = ai.missing_information.slice(0, 5).map(v => v.slice(0, 120));
  ai.requirement = ai.requirement.slice(0, 500);
  ai.product_requested = ai.product_requested.slice(0, 200);
  ai.next_action = ai.next_action.slice(0, 300);
  ai.summary = ai.summary.slice(0, 500);
  ai.qualification_reason = ai.qualification_reason.slice(0, 500);
} catch (e) {
  ai_status = 'fallback';
  ai_error = String(e.message || e).slice(0, 300);
  ai = null;
}

let score = null;
let lead_class = ai ? 'Invalid' : 'Needs review';

if (ai && ai.qualification_status === 'qualified') {
  score = clamp(ai.fit) * W_FIT
    + clamp(ai.intent) * W_INTENT
    + BUDGET_POINTS[ai.budget_signal]
    + URGENCY_POINTS[ai.urgency];
  lead_class = score >= HOT ? 'Hot' : score >= WARM ? 'Warm' : 'Cold';
}

if (ai && ai.qualification_status === 'invalid') {
  score = null;
  lead_class = 'Invalid';
}

const q = ai || {
  qualification_status: 'invalid',
  requirement: '',
  product_requested: '',
  budget_signal: 'none',
  urgency: 'low',
  fit: 0,
  intent: 0,
  pain_points: [],
  next_action: 'Manual review: AI qualification failed',
  summary: lead.message.slice(0, 300),
  missing_information: ['AI qualification output unavailable'],
  qualification_reason: 'AI qualification failed and the lead requires manual review'
};

const [firstname, ...rest] = lead.name.split(' ');
const summaryText = [
  q.summary,
  q.requirement && `Requirement: ${q.requirement}`,
  q.product_requested && `Product: ${q.product_requested}`,
  q.pain_points?.length && `Pain points: ${q.pain_points.join('; ')}`,
  q.qualification_reason && `Qualification: ${q.qualification_reason}`,
  q.missing_information?.length && `Missing: ${q.missing_information.join('; ')}`
].filter(Boolean).join('\n');

const properties = {
  email: lead.email,
  firstname,
  lastname: rest.join(' '),
  company: lead.company,
  hs_lead_status: lead_class === 'Hot' || lead_class === 'Warm' ? 'NEW' : 'UNQUALIFIED',
  ai_lead_score: score ?? '',
  ai_lead_class: ai_status === 'fallback' ? 'Needs review' : lead_class,
  ai_budget_signal: q.budget_signal,
  ai_urgency: q.urgency,
  ai_next_action: q.next_action,
  ai_summary: summaryText
};

if (lead.phone) properties.phone = lead.phone;

return [{ json: {
  ...lead,
  status: ai_status === 'fallback' ? 'fallback' : (q.qualification_status === 'invalid' ? 'invalid' : 'qualified'),
  ai_status,
  ai_error,
  qualification_status: ai_status === 'fallback' ? 'fallback' : q.qualification_status,
  qualification_reason: q.qualification_reason,
  missing_information: q.missing_information,
  score,
  lead_class,
  requirement: q.requirement,
  product_requested: q.product_requested,
  budget_signal: q.budget_signal,
  urgency: q.urgency,
  pain_points: q.pain_points,
  next_action: q.next_action,
  summary: q.summary,
  hubspot_body: { inputs: [ { idProperty: 'email', id: lead.email, properties } ] }
}}];

// Combine scored lead with HubSpot result. CRM failure is logged, then raised to the Error workflow.
const HUBSPOT_PORTAL_ID = 'REPLACE_WITH_PORTAL_ID';
const base = { ...$('Parse AI & Score').first().json };
delete base.hubspot_body;
const r = $json;
const id = r.results?.[0]?.id || '';
const failed = Boolean(r.error) || !id;
return [{ json: {
  ...base,
  hubspot_id: id,
  hubspot_url: id ? `https://app.hubspot.com/contacts/${HUBSPOT_PORTAL_ID}/record/0-1/${id}` : '',
  crm_status: failed ? 'failed' : 'ok',
  crm_error: failed ? String(r.error?.message || r.error || 'no id in response').slice(0, 300) : ''
}}];

